const rows = $input.all().map(i => i.json);
const byOffice = {};
for (const r of rows) {
  if (!byOffice[r.office_name]) {
    byOffice[r.office_name] = { asset_count: 0, delta: 0, rental_risk: r.open_rental_risk_flags };
  }
  byOffice[r.office_name].asset_count += Number(r.asset_count);
  byOffice[r.office_name].delta += Number(r.delta_vs_prior_week ?? 0);
}
const totalAssets = rows.reduce((s, r) => s + Number(r.asset_count), 0);
const today = new Date();
const monday = new Date(today);
monday.setDate(today.getDate() - ((today.getDay() + 6) % 7));
const weekOfStr = monday.toLocaleDateString('en-IN', { year: 'numeric', month: 'short', day: 'numeric' });

const subject = `IT Ops Weekly Summary \u2014 Week of ${weekOfStr}`;
let html = `<h3>IT Ops Weekly Summary \u2014 Week of ${weekOfStr}</h3>`;
html += `<table border="1" cellpadding="6" cellspacing="0"><tr><th>Office</th><th>Assets</th><th>\u0394 vs prior week</th><th>Open rental-risk flags</th></tr>`;
for (const [office, d] of Object.entries(byOffice)) {
  const sign = d.delta > 0 ? '+' : '';
  html += `<tr><td>${office}</td><td>${d.asset_count}</td><td>${sign}${d.delta}</td><td>${d.rental_risk}</td></tr>`;
}
html += `</table>`;
html += `<p><b>Total: ${totalAssets} assets across ${Object.keys(byOffice).length} offices</b></p>`;

return [{ json: { subject, html, row_count: rows.length } }];

const gmail = $('Send weekly digest').item.json;
const rowCount = $('Build weekly digest text').item.json.row_count;
const messageId = gmail.id ?? null;
return [{ json: {
  run_name: 'weekly_it_summary_digest',
  rows_pushed: rowCount,
  api_response_status: messageId ? String(messageId) : 'sent',
  status: 'success'
} }];
